'use strict';
const model=new AFReviewModel.ExportModel(),copyPolicy=new AFReviewModel.CopyPolicy();
const product=document.getElementById('product'),rows=document.getElementById('rows'),cover=document.getElementById('cover'),message=document.getElementById('message'),content=document.getElementById('message-content'),ok=document.getElementById('message-ok'),title=document.getElementById('message-title'),frame=document.getElementById('drag-frame');
const byId=id=>document.getElementById(id),reviewEvents=[];let messages=[],messageActives=0;
function log(text){reviewEvents.push(text);byId('review-log').textContent=reviewEvents.join('\n');}
function state(){const states=[model.rows.length?'ST-02':'ST-01'];if(model.active)states.push('ST-03');if(model.rows.some(r=>r.result!==''))states.push('ST-04');if(!message.hidden)states.push('ST-05');if(byId('policy-on').checked)states.push('ST-06');product.dataset.stateId=states.join(' ');}
// E-11 CSRUtil original lines 321-326: acquisition attempts focus for button-type active controls.
function acquireCover(){try{const active=document.activeElement;if(active&&active.getAttribute('type')&&/button/i.test(active.getAttribute('type')))window.focus();}catch(e){window.console&&console.log('[CSRUtil][createCoverPage] cant read activeElement!'+e);}}
function coverState(){cover.hidden=!(model.active||messageActives);state();}
function sync(){model.insrType=byId('insrType').value;model.prodType=byId('prodType').value;for(const r of model.rows){r.id=byId('id-'+r.key).value;r.policy=byId('policy-'+r.key).value;}}
function colorRows(){for(let i=0;i<model.rows.length;i++)byId('row-'+model.rows[i].key).className=i%2?'row-even':'row-odd';}
function add(){const r=model.add(),tr=document.createElement('tr');tr.id='row-'+r.key;tr.innerHTML=`<td class="center-cell"><input type="button" class="button" value="刪除此列" data-ui-id="UI-06" data-flow-id="FLOW-03"></td><td class="center-cell"><input type="text" size="12" maxlength="10" name="I_ID" id="id-${r.key}" class="textBox2" data-ui-id="UI-07" aria-label="被保人ID"></td><td class="center-cell"><textarea rows="3" cols="30" name="POLICY_NO" id="policy-${r.key}" class="textBox2" data-ui-id="UI-07" aria-label="保單號碼"></textarea></td><td id="result-${r.key}" data-ui-id="UI-08"></td>`;tr.querySelector('input[type=button]').addEventListener('click',()=>{sync();model.remove(r.key);tr.remove();colorRows();state();});rows.append(tr);colorRows();state();}
function chooseRequests(){const s=byId('request-choice');s.replaceChildren();for(const r of model.requests.filter(r=>!r.done)){const o=document.createElement('option');o.value=r.id;o.textContent=r.id;s.append(o);}}
function submit(){sync();const req=model.submit();if(req.error){alert(req.error);return;}log('已知匯出邊界 '+req.id+'：'+JSON.stringify(req.body));chooseRequests();acquireCover();coverState();}
function renderResults(){for(const r of model.rows)byId('result-'+r.key).innerHTML=String(r.result);state();}
function closeMessage(e){e.stopPropagation();if(message.hidden||!message.parentNode)return;message.hidden=true;messageActives=Math.max(0,messageActives-1);messages=[];content.innerHTML='';if(!(model.active||messageActives))acquireCover();coverState();}
ok.addEventListener('click',closeMessage);
function showMessage(msg){const normalized=AFReviewModel.normalizeMessage(msg),x=normalized.length*15;if(!messages.includes(normalized))messages.push(normalized);acquireCover();if(content.innerText===''){message.hidden=false;messageActives++;content.innerHTML=normalized;const keyInstance=function(e){document.removeEventListener('keypress',keyInstance);if([13,27,32].includes(e.keyCode)&&!message.hidden&&message.parentNode){ok.click();e.preventDefault();e.stopPropagation();}};document.addEventListener('keypress',keyInstance);message.style.width=Math.max(180,Math.min(600,x))+'px';}else{if(content.offsetWidth<588&&content.offsetWidth<x&&x>180)message.style.width=Math.min(600,x)+'px';content.innerHTML=messages.join('<br/>');}message.hidden=false;document.body.append(message);message.style.top=parseInt(document.body.clientHeight/4+window.scrollY,10)+'px';message.style.left=parseInt((document.body.clientWidth-message.offsetWidth)/2+window.scrollX,10)+'px';ok.focus();coverState();}
function complete(resp){const e=resp.ErrMsg;if(!e){coverState();return;}const str=e.displayMsgDescs.split('\\n').map(s=>s+'\n').join('').trim(),isError=e.returnCode!=0,id=e.msgid;let bottom=byId('bottom-exists').checked;if(bottom&&str)log('合成底部通知：'+(isError?'紅':'藍')+' 訊息：'+str);const mode=byId('system-mode').value;let text='';if(mode!=='other'){if(isError&&id&&id.length>17)text='錯誤編號：\n'+id+'\n訊息說明：\n';text+=str;if(isError||(str&&mode!=='EP'))showMessage(text);}else{coverState();if(isError){if(id&&id.length>17)text='錯誤編號：\n'+id+'\n';alert(text+'訊息說明：\n'+str);}else if(str&&!bottom)alert('訊息說明：\n'+str);}coverState();}
function inject(){sync();let map;try{map=JSON.parse(byId('response-map').value);}catch(e){log('審閱工具 JSON 無法解析：'+e.message);return;}const req=byId('request-choice').value;if(!req){log('審閱工具：請先建立請求');return;}const resp={rtnMap:map,fileName:byId('file-name').value,ErrMsg:{returnCode:Number(byId('return-code').value),displayMsgDescs:byId('response-msg').value,msgid:byId('message-id').value}};const result=model.receive(req,resp);if(result.error)alert('Error :\nurl : 審閱工具的已知匯出邊界\nparams: '+JSON.stringify(model.requests.find(r=>r.id===req).body)+'\nException: \nmessage='+result.error.message+'\n');else renderResults();for(const d of model.downloads.filter(d=>d.request===req))log('回填後到下載邊界 '+req+'：'+d.fileName+'；TODO-02/04，沒有檔案／外部連線');complete(resp);chooseRequests();}
let dragOffset;
function down(e){title.removeEventListener('mousedown',down);const rect=message.getBoundingClientRect(),left=rect.left+scrollX,top=rect.top+scrollY;dragOffset={x:e.pageX-left,y:e.pageY-top};Object.assign(frame.style,{width:message.offsetWidth+'px',height:message.offsetHeight+'px',left:left+'px',top:top+'px'});frame.hidden=false;document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);}
function move(e){e.preventDefault();e.stopPropagation();frame.style.left=e.pageX-dragOffset.x+'px';frame.style.top=e.pageY-dragOffset.y+'px';message.remove();}
function up(e){document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);e.preventDefault();e.stopPropagation();message.style.left=parseInt(frame.style.left,10)+'px';message.style.top=parseInt(frame.style.top,10)+'px';frame.hidden=true;document.body.append(message);title.addEventListener('mousedown',down);}
title.addEventListener('mousedown',down);
byId('addBtn').addEventListener('click',add);byId('exportBtn').addEventListener('click',submit);byId('frm').addEventListener('submit',e=>e.preventDefault());
document.addEventListener('click',e=>{if(e.target.closest('[data-review-tools]'))return;const t=e.target.type;if(t&&'button,submit'.indexOf(t)!==-1)log('產品按鈕動作後：嘗試清除外部底部訊息（TODO-01）');});
byId('inject').addEventListener('click',inject);byId('enqueue').addEventListener('click',submit);byId('inject-target').addEventListener('click',()=>log('目標合成契約 {code:500,msg:動態原因,data:null}；TODO-02：無逐列map，未映射舊回呼／未偽裝已回填。請求保持等待已知邊界。'));
byId('show-custom').addEventListener('click',()=>showMessage(byId('custom-msg').value));
byId('policy-on').addEventListener('change',()=>{document.body.classList.toggle('policy-enabled',byId('policy-on').checked);state();});
const policyText={cut:'依據資安政策，不開放剪下功能',print:'依據資安政策，不開放列印功能',beforeprint:'依據資安政策，不開放列印功能'};
function policyStop(e){if(!byId('policy-on').checked)return;e.preventDefault();e.stopPropagation();if(policyText[e.type])alert(policyText[e.type]);}
for(const type of ['contextmenu','print','beforeprint','cut'])document.body.addEventListener(type,policyStop,true);
window.addEventListener('keydown',e=>{if(!byId('policy-on').checked||!e.ctrlKey)return;const text={65:'依據資安政策，不開放全選功能',88:policyText.cut,83:'依據資安政策，不開放頁面儲存功能',80:policyText.print}[e.keyCode];if(text){e.preventDefault();e.stopPropagation();alert(text);}},true);
document.body.addEventListener('copy',()=>{if(!byId('policy-on').checked)return;const a=document.activeElement,text=a&&a.tagName.toLowerCase()==='textarea'?a.value.substring(a.selectionStart,a.selectionEnd):window.getSelection().toString(),record=copyPolicy.copy(text,Date.now());if(record){setTimeout(()=>{copyPolicy.last='';log('独立60秒到期：去重記錄清空');},60000);log('複製軌跡邊界（合成，未寫入）：'+JSON.stringify(record)+'；TODO-04');}},true);
state();log('離線初始：L/AT、0列。入口／底部／政策來源／浮水印與未知載入副作用維持 TODO。');
